INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1167540-ee390', 'stk-user1091', 'EE 390', 'info', '{"desc": "السلام عليكم\n\nهذا الكورس عسل لكن للي يفهمه صح\n\nباختصار اللي يفهم البرمجة بلغة ال Assembly ويكثر من حل الأمثلة والتمارين ياخذ فيه إن شاء الله A بالراحة\n\nأما اللي ما يفهمه بيتذمر منه وبيستصعبه\n\nأخذتها مع الدكتور شيخ شريف في الصيف\n\nوملخصات شيخ شريف الصراحة كافية ووافية بالأمثلة\nيعني ما تحتاج كتاب لكن الكتاب مكمل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/4", "user": "user1091", "ts": 1358848768000, "tid": 120705, "pn": 4}}', 1358848768000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1374102-ee390', 'stk-mythm', 'EE 390', 'info', '{"desc": "كورس لغة برمجة assembly\n\nنوت الدكتور شيخ شريف جدا ممتازه لها الكورس وكافية\n\nاللاب سهل وممتع\n\nالكورس سهل لكن يبيلك تشتغل من البداية ( اشان تفهم لغة البرمجة صح )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/7", "user": "mythm", "ts": 1401391399000, "tid": 120705, "pn": 7}}', 1401391399000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457540-ee390', 'stk-ziyad_al-amoud', 'EE 390', 'info', '{"desc": "الكورس يتغير كل فترة على حسب كلام الدكتور شريف شيخ، قبل كان متركز اكثر في الmicroprocessors(8086/8088) لكن حاليا مركز أكثر في الmicrocontrollers(8051) لكن صعوبة الكورس ما أظن تغيرت، اللهم ما راح تلقى اولد اقزام. كورس ممتع.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/8", "user": "Ziyad_Al-Amoud", "ts": 1473770511000, "tid": 120705, "pn": 8}}', 1473770511000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467274-ee390', 'stk-abo-da7m', 'EE 390', 'info', '{"desc": "أخذته الفصل 161 مع الدكتور شريف شيخ.\n\nجودة المقرر بشكل عام\nجيد ومفيد بس ما يستاهل 4 كريدت\n\nالمواضيع التي يغطيها المقرر\nباختصار، البرمجة بلغة assembly مثل ما ال ICS103 برمجة بلغة C\nوهذا يعني أنه ما يعتمد على مواد الكهرب ( يعتمد بكشل خفيف على 200 بس) وتقدر تقدمه أو تأخره بدون ضرر.\n\nالكتاب المستخدم للمقرر\nThe 8051 Microcontroller and Embedded Systems: Using Assembly and C\nهذا يعتمدون عليه بمعظم المقرر، مفيد وسلس وواضح جدا. تمارينه جيدة ومفدية بس ما تأهلك للمياجر صح لإن فيه تركات من رؤوس الدكاترة ما يغطيها الكتاب.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nأسئلة الإختبارات كانت سيئة ومليانه أفخاخ وكإنهم يحاولون يمقلبونك موب يختبرون فهمك لأساسيات المادة.\n\nمدى فائدته في الناحية التطبيقية\nمفيد جدا ويقدرون يخلونه أكثر فايدة لو ركزوا على التطبيقات العملية للمادة وتركوا شغل المقالب بالأسئلة.\n\nملاحظات:\n* من أكثر المقررات اللي رفعت ضغطي. المفترض يكون سهل ومفيد بس نظام الاختبارات وطريقة الأسئلة كانت في غاية السوء.\n* لابه مفيد جدا وخفيف مرة. ركز عليه واستفد من حضورك، بيفيدك بالاختبارات وبفهم المادة.\n* من ناحية المفاهيم تعتبر المادة سهلة لحد بعيد وما به تعقيد مقارنة ب 370 و 380.\n* لو كان أدائك بالكهرب مش ولا بد، هالمادة فرصة للتعويض لإنه ما تعتمد على غيره من المواد وتقدر تجيب به قريد لا شديت.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/9", "user": "abo-da7m", "ts": 1485769898000, "tid": 120705, "pn": 9}}', 1485769898000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1479246-ee390', 'stk-mr.a1', 'EE 390', 'info', '{"desc": "Term 163 with Dr. Mohammed Mohandes\n\nجودة المقرر بشكل عام\nيتحدث المقرر عن المتحكم الدقيق (Microcontroller) من نوع 8051 ، وعن طريقة برمجته بلغة Assembly. مفيد في مجال الحواسيب ، ويدخل في أغلب المجالات اللي تحتاج فيها متحكم.\n\nالمواضيع التي يغطيها المقرر\nالمنهج مزدحم اشوي:\n\nطبعا الدكتور حذف تشابتر 7 و 13 ، بالإضافة إلى الـ AVR اللي يعتبر اختياري ومو داخل ضمن المنهج.\n\nالكتاب المستخدم للمقرر\nكتاب المادة جيد جدا ، أمثلته ممتازة للفهم ، يعيبه أنه يطول شرح الكونسبت اشوي.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nأمثلة الكتاب ممتازة للفهم ، أسئلة الهومورك فيها بعض الأفكار ، أما الاختبارات فيها أفكار وتريكات كثيرة جدا.\n\nمدى فائدته في الناحية التطبيقية\nالمتحكم الدقيق مهم جدا في كثير من المجالات ويدخل في كثير من التطبيقات الكهربائية ، وأغلب الأجهزة اللي حولنا تستخدمه ؛ لأنه عبارة عن كمبيوتر ذو مهمة واحدة وبسعر أرخص من الكمبيوتر نفسه. فمن المهم للمهندس الكهربائي يعرف كيف يتعامل معه.\n\nإضافات:\n١. أسئلة الكتاب والهومورك ما راح تكفيك عشان تستعد للاختبارات ، ضروري جدا تشوف أولد اقزامات عشان تعرف بعض تريكات الدكاترة.\n٢. المادة متغيرة من فترة لأخرى ، فمو شرط نفس المنهج اللي هنا تشوفه بعد كم سنة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/10", "user": "Mr.A1", "ts": 1503574327000, "tid": 120705, "pn": 10}}', 1503574327000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1497939-ee390', 'stk-abdullah2015', 'EE 390', 'info', '{"desc": "أخذت المادة مع الدكتور محمد المهندس في ترم 173\n\nجودة المقرر بشكل عام:\nممتازة.\n\nالمواضيع التي يغطيها المقرر:\nراح تدرس لغة الAssembly في المادة بشكل أساسي، وكذلك راح تتطرق لمعمارية المتحكم الدقيق “Microcontroller”.\nنظام المادة شبيه بنظام الICS103 من ناحية إنه تبدأ بدروس سهلة وتبدأ تصعب تدريجيًا، وكذلك من ناحية إن اللي تأخذه في البداية تظل تستخدمه طول السمستر.\n\nالكتاب المستخدم للمقرر:\nhttps://images-na.ssl-images-amazon.com/images/I/51hDIxUt-AL._SX360_BO1,204,203,200_.jpg\nجميل وممتاز، لكن مشكلته إنه يسهب كثيرًا في التفاصيل ويحتاج وقت للقراءة.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nالأمثلة اللي موجودة في الكتاب مفيدة جدًا في فهم مواضيع المادة.\n\nمدى فائدته في الناحية التطبيقية:\nأعتقد إن هذه المادة من أهم المواد في قسم الهندسة الكهربائية اللي لها تطبيقات عملية ومباشرة، ليست فقط مهمة في الأشياء المتعلقة بالهندسة الكهربائية، إنما أيضًا في مجالات أخرى غير الهندسة الكهربائية مثل الهندسة الميكانيكية والكيميائية. هذه الأيام المتحكم الدقيق موجود في تطبيقات كثيرة في حياتنا اليومية. السيارة، مثلًا، فيها متحكم دقيق للتحكم بالمحرك الخاص بها، طبعًا السيارة فيها أكثر من متحكم دقيق في أماكن مختلفة، لكن المحرك مجرد مثال (طبعًا أتكلم عن السيارات الحديثة). كذلك المتحكم الدقيق موجود للتحكم بالآلات في المصانع. أيضًا من الأمثلة الواضحة اللي نشوفها في حياتنا اليومية اللي المتحكم الدقيق له علاقة كبيرة فيها هو المصعد، وغيره الكثير.\n\nإذا كنت تبي تفاصيل وأمثلة أكثر، فقط أكتب في قوقل\nExamples of Embedded Systems\nأو\nApplications of microcontroller\nوراح تشوف عشرات التطبيقات للمتحكم الدقيق في مختلف مجالات الحياة.\nوإذا حاب تتوسع في تطبيقات المتحكم الدقيق في مجال معين، السيارات مثلًا، أكتب\nEmbedded Systems in automobiles\nأو\nApplications of microcontroller in automobiles\n\nملاحظات عامة:\n- المادة تعتبر من أسهل المواد في قسم الهندسة الكهربائية باجماع الكثير، خصوصًا إذا كنت تحب البرمجة، هذا راح يسهل عليك المادة كثيرًا، ويمديك تطلع منها بقريد طيب إذا شديت حيلك.\n- المادة غير معتمدة بشكل كبير على EE200، فقط تحتاج إلى بعض الأساسيات، وهذه الأساسيات ستتكرر معك طول السمستر فيعني أنه ربما تواجه صعوبات في البداية فقط، لكن مع مرور الوقت راح تمشي أمورك فيما يتعلق بشغلات الEE200.\n- النوت اللي يرفعها الدكتور المهندس على البلاك بورد ممتازة كمصدر أساسي للمذاكرة، وكذلك نوت الدكتور شريف الشيخ ممتازة.\n- اطلاعك على الأولد اقزامز أمر مهم جدًا.\n- لاب المادة جميل وراح تطبق فيه ما تدرسه في اللكتشر بالضبط في معظم اللابات، بعكس لاب الEE200 اللي كان في صوب واللكتشر في صوب ثاني في معظم الأحيان.\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/11", "user": "Abdullah2015", "ts": 1534631630000, "tid": 120705, "pn": 11}}', 1534631630000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504002-ee390', 'stk-ali_g', 'EE 390', 'info', '{"desc": "مع الدكتور شريف شيخ في ترم 181\n\nجودة المقرر بشكل عام:\nمنظم\n\nالمواضيع التي يغطيها المقرر:\nطبعا باوضح نقطة مهمة قبل: assembly صح انها قديمة من 1951 وهي اساس الانظمة,\nولكن تعلمك كيف c program يعمل و وتقوي لوجيك حقك. فالغات البرمجة تختلف ولكن تتشابه في اللوجيك.\nالمواضيع:\n1-انواع microcontroller/micropossor\n2- pins of 8051 microcontroller\n3- instructions of 8051 (بسيط واساس المادة)\n4-delay time (جدا مهم وبسيط)\n5- Arithmetic الجمع والطرح والقسمة والضرب وغيرها (سهل لكن عليها تركات)\n6- C Program راجع ICS 103, (حقيين الاردوينو راح يرتاحوا منها)\n7- second type of time delay plus counter (متوسط)\n8- Serial communication recieve and transfer data (هذا الموضوع الحقيقة صعب تفهمه مع الدكتور لازم تتطلع على الكتاب عشان تتجنب التركات)\n9-Interrupt (صعب بسبب انه تخيل ان عندك ثلاث اكواد يشتغلوا مع بعض وكل واحد ياثر في ثاني, قبل كانت تمشي على كود واحد يمشي بتسلسل واحد فاعطيه جدية عشان اختبار النهائي)\n10-ADC سهل ولكن محذوف من الاختبار\n11-Memory types and Interfacing to External memory (هذا سهل ويحتاج تركييييز مع الدكتور والا راح تتعب في المذاكرة راح يعلمك كيف الكمبيوتر يشتغل من روم ورام)\n\nالكتاب المستخدم للمقرر:\nشرحه ممتاز الكتاب, خليه مرجع لك اذا عندك مشاكل.\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nتمرن على اسئلة اخر كتاب مهمة\n\nمدى فائدته في الناحية التطبيقية:\nassembly تقدر تشغل عليه تشتري 8051, وشوف مشاريع من موقع\n8051 Projects - Circuits and Projects Based on 8051 Microcontroller\n\nولكن باضافة c program في المادة زادت اللوجيك عندي عشان الاردوينو مع اختلافات بسيطة بينهم\nوالاردويو بحر مشاريع كل ما تعمقت تشوف انك بدائي فيه\n\nإضافات:\n1- ما راح اقول انها سهلة ومادة قريد, ولكن الافخاخ كثيرة فيها عشان تتجنبها تحتاج تتمر على اولد اكزام والكتاب\n2- اللاب مهم كتمرين لك بعد المحاضرة فاستغلها تفهما زين\n3- اذا تبي الوصف السري حمل Assembler MIDE-51 (هذا المحاكي الي راح تشتغل عليه في لاب ) اذا عندك مشكلة خليه هو اوفس الاور", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/12", "user": "Ali_G", "ts": 1545658549000, "tid": 120705, "pn": 12}}', 1545658549000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1526522-ee390', 'stk-user11724', 'EE 390', 'info', '{"desc": "EE390-Term201\n\nالمادة في الاونلاين ممتازة لان الكونسبت فيها شبه سهل، تبدأ من الاساسيات مثل الICS103 واعتقد انها اسهل كمان، كل ما كان حس البرمجة عندك اقوى تكون المادة اسهل واسهل، ولكن الميجر اصعب بمراحل من السلايدات ف انتبه لازم تحل اولد اقزام ولا درجاتك بتطير، اللاب حق المادة مو صعب ولا فيه بريلاب ولا اسايمنت، عندك بس اللاب ريبورت والكويزات، المادة نسيبا تعتبر سهلة ولكن لا تهملها عشان ما تضيع قريداتها، واعيد مرة ثانية انتبه للمياجر تراها مو سهلة مثل الكونسبت الي تاخذه في اللكتشر، والمادة مترابطة بشكل بسيط مو مثل ICS103 ولكن ممكن تحتاج افكار كثيرة في سؤال واحد، واعتقد مبادئ المادة اشوف انها مرتبطة بICS103 اكثر من EE200، بالتوفيق للجميع.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-digital-systems-engineering/120705/15", "user": "user11724", "ts": 1604559415000, "tid": 120705, "pn": 15}}', 1604559415000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1258797-ee390', 'stk-user7645', 'EE 390', 'info', '{"desc": "وعليكم السلام\n\nرد سابق لي :\n\nee390\n\nمادة سهله حقيفةً والمنهج مو طويل لإنها تتكلم بنسبة 80% عن لغة الأسمبلي ( مجرد أساسيات ) والجزء الأخير 20% عن المايكروبروسيسر هارد وير وهذا جزء قراءة مو أكثر وفهم .\n\nطبعاً تقدر تأخذ فكرة كاملة عن لغة الأسمبلي (باللغة العربية حتى تفهمها بشكل أكبر ) قبل ماتبدأ فيها بالسمستر الجاي وأضمن لك بتغطي الـ 80% من الكورس فقط بفهمك الملفين اللي بأضعها بالأسفل :\n\nhttps://www.dropbox.com/sh/rz40bwf4kq0ypmf/n6rmc6cpeo\n\n(الملفين تغطي 99% من لغة الأسمبلي اللي راح تأخذها والأوامر والعمليات وكتابة البرامج مع امثلة وحلول اطلع عليها وبتفهم اللغة بشكل كامل فيصير تروح للكلاسات وانت فاهم اللغة ومجرد تأكيد للمعلومات مو أكثر )\n\nوهذا ملف كامل فيه جميع ماتحتاجه للمادة ( واجبات وريبورتات وتلخيصات واختبارات والخ … ) :\n\nhttps://www.dropbox.com/sh/azicsd9kuifd04l/o6pqf9sncq\n\nوهذا ملف كامل يحوي على أسئلة وتمارين على لغة الأسمبلي حاول حلها بنفسك جميعاً وبتضمن الآي بلس بمشيئة الله :\n\nhttps://www.dropbox.com/sh/cwcngrjd3h8z7h3/kyoavgf-cx\n\nبكذا بتكون مغطي المادة بشكل كامل ، أما عن طريقة المذاكرة فحقيقة الكتاب مو سيء لكن إذا استعنت باللي وضعته بالأعلى مابتحتاج الكتاب بمشيئة الله (ماعدا بقسم الهاردوير ) أنصح بمراجعة الكتاب حتى تفهم بعض العمليات اللي يجريها المايكروبروسيسور .\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee390/148395/6", "user": "user7645", "ts": 1378151241000, "tid": 148395, "pn": 6}}', 1378151241000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p566788-ee390', 'stk-system2005', 'EE 390', 'srcP', '{"html": "مجموعة هوموركات ممكن تفيدك،،<br>بالتوفيق…<br><br>​<span data-fid=\"stk-f566788-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f566788-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f566788-0": {"name": "HW.zip", "v": "data:application/zip;base64,"}, "stk-f566788-1": {"name": "EE390.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-390-manual-solution/85442/2", "user": "system2005", "ts": 1268688798000, "tid": 85442, "pn": 2}}', 1268688798000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1144114-ee390', 'stk-hsooom', 'EE 390', 'srcP', '{"html": "شباب انا قاعد احل واحد من المياجر بس باقي ماكملت الحل هدا اللي حليته<br><br>​<span data-fid=\"stk-f1144114-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>IMG-20121218-02405.jpg1599×1199 186 KB", "files": {"stk-f1144114-0": {"name": "6-Exams_Major_2.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fdd0facc0eade097b5ec26e3127bf24a3d026720b5bc35093ffcc1ad5609d4f4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/old-exams-for-ee390/136517/7", "user": "Hsooom", "ts": 1355782317000, "tid": 136517, "pn": 7}}', 1355782317000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1087916-ee390', 'stk-user7645', 'EE 390', 'srcU', '{"html": "تفضل بالمرفقات ياغالي<br><br>​<span data-fid=\"stk-f1087916-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1087916-0": {"name": "EE 390 outline_121(1).doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syllabus-ee390/131313/2", "user": "user7645", "ts": 1346939269000, "tid": 131313, "pn": 2}}', 1346939269000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p445161-ee390', 'stk-user1508', 'EE 390', 'srcU', '{"html": "اخوي زيدان هذي حلول البرامج اللي طلبتها او شبيهه لها و لكنها غير مرتبه … و بالتوفيق ان شاء الله … و ارجو من الجميع الدعاء فقط<br><br>راجع المرفقات + يتبع الرد القادم<br><br>​<span data-fid=\"stk-f445161-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f445161-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f445161-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f445161-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f445161-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f445161-5\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f445161-6\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f445161-0": {"name": "prog1.txt", "v": "data:application/octet-stream;base64,"}, "stk-f445161-1": {"name": "prog2.txt", "v": "data:application/octet-stream;base64,"}, "stk-f445161-2": {"name": "prog3.txt", "v": "data:application/octet-stream;base64,"}, "stk-f445161-3": {"name": "prog4.txt", "v": "data:application/octet-stream;base64,"}, "stk-f445161-4": {"name": "prog5.txt", "v": "data:application/octet-stream;base64,"}, "stk-f445161-5": {"name": "prog6.txt", "v": "data:application/octet-stream;base64,"}, "stk-f445161-6": {"name": "prog7.txt", "v": "data:application/octet-stream;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee390/76404/4", "user": "user1508", "ts": 1249995736000, "tid": 76404, "pn": 4}}', 1249995736000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mqr-ee390', 'stk-mqr', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98369", "n": "Dr. I Al-Saihati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 390 LAB -Term 211\n\nالتحضير :يحضر في بداية الكلاس ينادي الاسماء\nطريقة الشرح : يشرح اللاب منول بطريقة غير مفهومة وبعدين يقولك ليش ما فهمت ويعطيك محاضرة انه انت فيه شىء بعقلك عشان كذا مو قادر تفهم ز\nالكويزات :سهله , بس فيها تركات\nالفاينلات : خيارات 15 سؤال ( متخبط لدرجة انه غير طريقة الاسئلة 1000 مرة )\nالقريد النهائي:A\nالصوت:جيد\nإضافات :\nغير متعاون مع الطلاب لدرجة يحسسك انك عدوه وانك ما عندك امانة ودايم تغش. قبل البروجكت تكلمت معاه وقعد يقولي انا بسوي البروجكت بنفسي و اعطيه الطلاب عشان اللي يغش اكشفه و ارسبه بالمادة + دايما يختلق الاعذار واذا جيته تراجع عن اي شىء يقولك ارسلي بالاميل انا مو فاضي و عندي طلاب كثير وما ادري ايش + نصيحة محب اذا تبي درجة حلوه بالاب لا تنزل عنده لانه من اسوء المدرسين اللي مروا علي بالجامعة + نسيت شىء بعد لاب 390 جدا سهل بس من قوة انه ما يعرف يشرح يلخبط عليك الامور ويقولك بعدين انا ما طلبتك تسوي كذا 😁 .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533116-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-al-saihati/98369/22", "user": "mqr", "ts": 1639995442000, "tid": 98369, "pn": 22}}]}', 1639995442000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee390', 'stk-user6130', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98376", "n": "Dr. K Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله ،،،\n\nEE 390 سمستر 121 ،،،\n\n(1) الشرح : متوسط أقل كفاءة من كورسات 200 و 207 لأن الدكتور أول مرة يدرس الكورس فما عنده الخبرة الكافية فيه حتى الآن.\n\n(2) الكويزات : سهلة و بعضها يجيبها من كويزات المهندس القديمة.\n\n(3) المياجر و الفاينلات : كومون و كانت سهلة ما عدا سؤال في ميجر 2 كان يحتاج إلى تفكير و كان عليه 10 درجات من 30 .\n\n(4) التحضير : ورقة توقع عليها و يمديك تحضر أخوياك بس انتبه يعرفك و تخلي أحد يحضرك لأنه بينشب لك كيف تحضر و أنت ما جيت ؟ 🤠 .\n\n(5) إضافات :\n\n* الدكتور أخلاقة عالية و طيب جداً بس للأسف أغلب الطلاب استغل هذي الطيبة في الغياب و تزويد الدرجات في المياجر و الكويزات .\n\n* بالنسبة للبروجكت كان كومون بروجكت و كان أسهل من بروجكتات السمسترات الماضية 3 برامج تسلم ملف exe فقط ما فيها ريبورت .\n\n(6) القريد النهائي : B+ .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164349-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-qureshi/98376/27", "user": "user6130", "ts": 1358204017000, "tid": 98376, "pn": 27}}]}', 1358204017000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jstnawwaf-ee390', 'stk-jstnawwaf', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98376", "n": "Dr. K Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 172\nأخذت معاه مادتين، EE390 و EE311\n\nالتحضير :\n\nورقة في آخر ربع ساعة يوزعها، وفي ال 390 كنت أجي آخر ربع ساعة وأحضر نفسي، عادي ما يقول شيء.\n\nطريقة الشرح :\nفي EE390 أشوفه أقل من عادي، ويميل للسوء، ما عجبتني طريقة شرحه، يطول ويسهب مرة في شرح أفكار بسيطة، كنت معتمد على الكتاب وعلى فهمي باللاب، الكتاب جدا ممتاز.\nأما EE311 فأصلا ما فيها شيء ينشرح.\n\nالكويزات :\nفي EE390 دائما كويزاته من الأمثلة اللي بالسلايدات.\nفي EE311 كويزاته بسيطة بس تحتاج تقرأ السلايدات وتفهمها قبل.\n\nالمياجر:\nفي EE390 المياجر كومون، وتصحيحه جدا ممتاز ويعطيك حقك.\nفي EE311 المياجر كومون، وفي التصحيح يعطيك حقك وزيادة.\n\nالفاينلات :\nكومون، في EE390 الفاينل لازم تكون مركز فيه، وإذا ما فهمت شيء ممكن تسأل الدكتور قريشي، جدا متعاون ممكن يفهمك المطلوب لو مو واضح.\nوفي 311 يحبون يعقدونها بأنهم يحطون ألغاز، لذلك خذ لك فرة بالإنترنت وابحث عن مسائل في الـ Lateral thinking\n\nالقريد النهائي:\nفي ال EE390 أخذت A+ وأعطي الدكتور B\nفي ال EE311 أخذت A وأعطي الدكتور A+\n\nالصوت:\nممتاز\n\nإضافات :\n\nالدكتور يريحك في EE311 ومو معطي المادة أكبر من حجمها، وأيضا جدا متعاون وتصحيحه ممتاز وقريب من الطلاب ويحب الإبداع، أنصحكم بأنكم تبدعون بالبرزنتيشن اللي في نهاية الكورس لأنه ممكن يرفعكم كثير\nفي EE390 أشوف حصته مملة، لذلك بس أحضر آخر ربع ساعة وأحضر نفسي، والمادة مش صعبة لكن تحتاج تدخل الاختبارات وأنت مركز وفاهم، لكنه أخلاق ومتعاون وما يظلمك.\nأتمنى أفدتكم، بالتوفيق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1493600-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-qureshi/98376/33", "user": "jstNawwaf", "ts": 1528024562000, "tid": 98376, "pn": 33}}]}', 1528024562000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_sufayan-ee390', 'stk-m_sufayan', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98376", "n": "Dr. K Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE390 lab 182\nالتحضير : --\nطريقة الشرح : يشرح لنا باللاب بشكل مختصر وبعض الاحيان يطولها عشان الاكسبيرمنت تكون بسيطة ف يبي يطول الوقت\nالكويزات : كويزات اللاب متوسطة مائلة للصعوبة\nالمياجر: --\nالفاينلات : فاينل الاب الاكسبرمنتال كان صعب وبكلاسنا مافيه الا واحد او اثنين خلص المطلوب بالوقت لكن فاينل الثيوري كان متوسط\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : الدكتور متعاون جدا ومايطلع من اللاب الا الكل طالع ومخلص تصحيحه بالريبورتس شوي يدقق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509023-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-qureshi/98376/37", "user": "m_sufayan", "ts": 1556283219000, "tid": 98376, "pn": 37}}, {"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE390 182\nالتحضير : ورقة تمشي عالطلاب\nطريقة الشرح : يعطينا نوته بالبلاكبورد ونطبعها كلها كبيرة الصراحة النوته هي اجزاء من الكتاب واذا جا يشرح يمشي عالنوته ويقول حددوا هذا واكتبوا هذا يعني شرحه يكون متفاعل كثير ودايم يمزح عشان نبتسم لأنه يقول اذا ابتسمتوا تفهمون اكثر … بالاخير شرحه ممتاز\nالكويزات : متوسطة\nالمياجر: بالسمستر اللي منزل فيه كان هو الدكتور الوحيد ف ماخذ راحته الدكتور ميجر 1 كان متوسط والثاني كان شوي صعب\nالفاينلات : متوسط\nالقريد النهائي: A+\nالصوت: واضح جدا\nإضافات : الدكتور متعاون ويعطي نصائح لك كطالب وكمهندس , الصراحة دكتور ممتاز وتصحيحه كذلك مو شديد مرة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509027-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/19", "user": "m_sufayan", "ts": 1556285241000, "tid": 98527, "pn": 19}}]}', 1556283219000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10237-ee390', 'stk-user10237', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98376", "n": "Dr. K Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE390 lab 182\nالتحضير : عنده policy من الديبارمنت ويمشي عليها بالحرف زي اي لاب انستركشر.\n\nطريقة الشرح : عنده نسخة الكترونية من الكتاب يشغلها عالبروجكتر ويشرحها.\n\nالكويزات : 3 كويزات كلها عليها 2%, يحب يتعمق في المواضيع ويجيب اسئلة لكشتر اكثر من كونها لاب كويز.\n\nالفاينلات : فيه اكسبرمنتل وفيه ثيورتكل، الاكسبرمنتال ماكان صعب لكن طويل وفيه تفاصيل وااجد، الثيورتكل نفس الكويز تقريبا.\n\nالقريد النهائي: الدكتور جيد ويحاول يمشي وضع الطلاب ويوضح لهم قدر الامكان. الدكتور تخصصه communication ما هو متخصص ديجيتال اصلا، ما عنده خبرة كافية بهالمجال فبعض المشاكل اللي تصير ما يعرفلها.\n\nالصوت: واضح\n\nإضافات: يفضل انك تعطيه الريبورت بفورمات يحددها بداية السمستر وانت بكيفك، يقول ما يحتاج تضيع اوراق عالفاضي، عطني الزبدة بريبورتاتك. عشان كذا يدقق واجد بالتفاصيل ويخصم على اقل شي عشان الافرج يتعدل في النهاية. وفي الاخير جلدنا في النهاية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509187-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-qureshi/98376/38", "user": "user10237", "ts": 1556607863000, "tid": 98376, "pn": 38}}]}', 1556607863000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11724-ee390', 'stk-user11724', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term201 - EE390 LAB\nالتحضير: يحضر اكثر من مرة ويصور الشاشة على الحاضرين في زووم\nطريقة الشرح : الدكتور متمكن من الشرح وفاهم لانه كان يدرس لكتشر\nالكويزات : وسط تميل للصعوبة وبعض الاحيان تكون الاسئلة غريبة (نفس تفكير دكاترة اللاب)\nالقريد النهائي: B+\nالصوت: غالبا يكون واضح بس يتنفس في المايك كثير\nإضافات : الدكتور يتحلطم كثير بسبب الاونلاين وكورونا ويهدد كثير، يعني لو ما حليتوا هذا السؤال بخصم واغيب و…، ولكنه متساهل في تصحيح الريبورتات ويشرح لنا على “المانوال سلوشن” (وافهم يا فهيم)\nعموما اشوفه خيار كويس مقارنة بالي ياخذون مع كمال.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528015-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/22", "user": "user11724", "ts": 1611152348000, "tid": 98527, "pn": 22}}, {"id": "stk-dr-f98376", "n": "Dr. K Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term201 - EE390\n\nالتحضير: ينادي بالاسماء في مايكروسوفت تيمز، في البداية كان التحضير في نهاية المحاضرة بعدين شاف بعض الناس تجي متأخر وصار يحضر عشوائي.\nطريقة الشرح: يشرح من نوتاته وشخصيا استخدمتها وكانت ممتازة وفيه طلاب طلبوا ممنا نرسلها لهم (لانها كويسة).\nالكويزات : وسط تميل للسهولة واتوقع الافرج كان عالي فيها، ف انتبه تخبص.\nالميدتيرم: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح ولغته كويسة\nاضافات: الدكتور طيب ومتعاون لابعد حد، الطلاب هم الي حددوا جميع اوقات الكويزات والواجبات، وما عارضنا ابدا، الدكتور متميز جدا من هذي الناحية ويرد على الايميلات بسرعة.\nيعيبه انه قبل الفاينل انقطع تواصله مع الطلاب بشكل غريب وما نعرف الافرج ولا الكلاس وورك، شفنا درجة الفاينل والقريد النهائي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528022-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-qureshi/98376/45", "user": "user11724", "ts": 1611175245000, "tid": 98376, "pn": 45}}]}', 1611152348000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2781-ee390', 'stk-user2781', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98395", "n": "Dr. T Noman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لاب ee 390 - ترم 093\n\nكان شرحة مرررره تمام\nوطبعاً المادة هذي تعتمد على اللاب بشكل كبير\n\nبس الي يعيبه انه يتأخر بالريبورتات\nما جابها لنا إلا نهاية الترم كلها\n\nويطلعك اول ما تخلص\nويفهمك بشكل تمام التمام\n\nانصح فيه وبشدة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779700-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/t-noman/98395/2", "user": "user2781", "ts": 1296489444000, "tid": 98395, "pn": 2}}]}', 1296489444000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mysterious-ee390', 'stk-mysterious', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98396", "n": "Dr. M Mohandes", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ,\n\nبطوّل عليكم شويتين 🙂\n\nالدكتور أخذت معه EE390 ترم 133 ,\n\nالمادة كلها برمجة كأنها ICS103 والفرق فقط في اللغة Assembly ,\n\nالسمستر هذا انتكبنا لأن المتيريال جديد تماماً غير عن السمسترات الماضية ,\n\nما فيه لا كتاب !! ولا أولد إكزام ولا كويزز ولا هومورك قديمة نقدر نستفيد منها ,\n\n-----------------\n\nالدكتور شريح ويشرح كل شيء من قلب ,\n\nلكنه عصبي جداً وأحياناً تصير معاملته سيئة جداً لأبعد الحدود ,\n\nوهذا للأسف صار لي بعد الفاينل , منقصني نسبتين من 100 خطأ في الجمع ,\n\nويوم عدلها قال ترى ما راح تغيّر قريدك ,\n\nومنقّص نسبتين عشان الـ Efficiency قلت له ليش ؟ قال مب شغلك !!\n\nقلت له طيب خلني أشرح لك ليش سويت كذا, قال ماني فاضي لك أسمع وش تقول ,\n\nقلت له طيب كم الكت بوينتس للقريدز ؟ قل هذا شيء للدكاترة ومب لازم تعرفه ,\n\nوالأسوأ من ذلك يقول : القريد إذا ما أخذته بيدك ما تاخذه بكلامك !!\n\nعموماً , أنا هنا طلعت وقلت مستحيل أكمل معه , ما فيه فايدة إذا كان حبيب طول السمستر وبالنهاية ووقت الجد يصير تعامله مثل ما ذُكر أعلاه ,\n\nهذي قصتي السمستر هذا ومعليش ع الإطالة D:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1391227-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-mohandes/98396/15", "user": "Mysterious", "ts": 1408528611000, "tid": 98396, "pn": 15}}]}', 1408528611000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ee390', 'stk-mr.a1', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f176829", "n": "Dr. Saifullah Shafiq", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 163 EE 390 (LAB)\n\nبنود التقييم :\n\nالتحضير :\nبداية اللاب بالاسماء. يعتمد أنظمة القسم في التأخير عن اللاب.\n\nطريقة الشرح :\nيعبي السبورة بكل الاشياء اللي يحتاجها ، بالإضافة إلى التاسكات المطلوبة ثم يبدأ يشرح. شرحه ممتاز نسبيا ويتجاوب مع أسئلة الطلاب ، يعيبه أنه على نغمة واحدة فإذا ما تركز معه مضبوط بتمل بسرعة وتتشتت. أيضا يطوّل في الشرح اشوي ، ما أدري هل السبب تمديد وقت اللابات هالصيف أو هو كذا أصلا.\n\nالكويزات :\nكثيرة مقارنة بلاب (أعطانا ٤ ، ويقول إنه يعطي ٥ في الترم العادي). مستوى الكويزات من متوسط إلى صعب ، وتحتاج مذاكرة كويسة.\n\nالمياجر:\nــ\n\nالفاينلات :\nصعب ، خصوصا إن الطلاب شادّين حيلهم فكان يبي يطيّح الآفرج ويرفعهم بعدين. سؤال واحد وفكرة جديدة عن اللي اشتغلته في اللاب.\n\nالقريد النهائي:\nA\n\nالصوت:\nمعتدل إلى ضعيف ، أكسنت هندي.\n\nإضافات :\n١. أعطانا بروجيكت سهل نسبيا ، الشغل على الكود -إذا بتشتغل على راحتك- ما يتعدى ساعتين. الريبورت كان يحتاج بعض الشغل والوقت ، وفي المناقشة كان متساهل وما دقق كثير.\n٢. متعاون في التصحيح وأوقات التسليم ، خصوصا الريبورتات. لأن الوقت قصير في الصيف (لابين اسبوعيا) قال لنا جمعوا ريبورتات الاسبوع وجيبوها الاسبوع الجاي. لكن هالكلام ما ينطبق على البري لاب.\n٣. بالنسبة لريبورتات التجارب ، يحاول يخففها قد ما يقدر ، وما يعقّد الوضع أو يطلب كلام كثير في الريبورت.\n٤. يجي يشيّك على كل جزء تسويه في اللاب ، وإذا شافك حاولت وما قدرت توصل لنتيجة يساعدك في الكود ويشرح لك الفكرة.\n٥. تقسيم الدرجات كالتالي:\nPrelabs: 1.5%\nReports: 2.5%\nQuizess: 5%\nProject: 3%\nFinal: 8%\nلاحظ أن ١٣ من ٢٠ على الاختبارات ، ومستواها صعب اشوي. لذلك إذا تبي درجة عالية مع أ. سيف الله حاول تطلع بأكبر درجة في الاختبارات ، الباقي سهل إنك تجيب فيهم درجات عالية.\n\nفي المجمل ، أستاذ خلوق وحبيب مع الطلاب ، متعاون وشرحه كويس ، بس لو يخف في اختباراته يصير مميز 😆", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479051-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saifullah-shafiq/176829/2", "user": "Mr.A1", "ts": 1503347995000, "tid": 176829, "pn": 2}}, {"id": "stk-dr-f98396", "n": "Dr. M Mohandes", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 163 EE 390\n\nبنود التقييم :\n\nالتحضير :\nبداية المحاضرة ، يدخل ويفتح ملف الاكسل على البروجيكتر ويحضر بالاسماء. ما يعترف بالتأخير ، إذا مر على اسمك وما رديت يحطك غايب.\n\nطريقة الشرح :\nسلايدات مسويها ، عبارة عن النقاط الاساسية مع أمثلة الكتاب ، ويستعمل السبورة إذا احتاج يوضح شيء.\nشرحه في المجمل حليو ، لكنه أحيانا يفوّت بعض النقاط المهمة ، خصوصا في نهاية المنهج.\n\nالكويزات :\nكثيرة ، تقريبا اخذنا ٨. مستواها سهل ، بعضها متوسط. طبعا ما يدري عن التصحيح ، يعطيها القريدر وهو يصحح.\n\nالمياجر:\nميدترم ، وهنا كانت النكبة. الله يهديه نسخه من جامعة ثانية بدون ما يقراه ، وضيّع علينا نص وقت الاختبار على سؤال ما شرح افكاره وفي الأخير حذفه. مستوى الميد كان وسط مائل للسهولة بس الدرجات كانت متوسطة.\n\nالفاينلات :\nشامل لكل المنهج ، سهل ، باستثناء آخر سؤال لأنه ما غطى الماتيريال حقه بشكل جيد.\n\nالقريد النهائي:\nA.\n\nالصوت:\nواضح ومسموع للجميع ، طول المحاضرة بالانجليزي.\n\nإضافات :\n١. يعطي مجموعة هوموركات طول الترم ، القريدر يصحح على المحاولة (يعني مو شرط تحله صح). يعيبه إنه غير منظم في مواعيد الهوموركات والكويزات ، متى ما مسكت معه قال لك بكرة أو بعد بكرة سلم الهومورك/فيه كويز.\n٢. السلايدات ما ينزلها على البلاك بورد ، لكنه ينزّل نوت د. شريف شيخ.\n٣. طبعا مثل ما يقول الدكتور:\n“This is a multidisciplinary course, that involves physical education”.\nمثلا خلص شرح نقطة ، يقول فيه أحد عنده سؤال ؟ ترفع يدك يقول لك تعال على السبورة ، يلا حل المثال وانا بساعدك 😆. البعض ممكن يتحسس أو يتضايق من هالحركة.\nطبعا ثق ثقة تامة إنك بتطلع على السبورة في يوم من الأيام ؛ لأنه يحفظ الطلاب ويعرف الناس اللي يسألون ويطلّعهم كثير. فإذا ما شاف أحد رافع يده بيدوّر الناس اللي ما يسألون كثير ويطلّعهم 😆.\n٤. الدكتور حبيب ويمزح مع الطلاب أحيانا ، ويحاول يتساعد معهم في التصحيح والمواعيد -لو طلبوا تعديل موعد شيء معين-.\n٥. أغلب اللي أعرفهم لما راحوا راجعوه على درجات الميدترم طلّع لهم بلاوي في إجاباتهم 😆 ، بس ما خصم شيء. فأنصحك لا تروح تراجعه إلا وأنت ضامن.\n٦. إنتبه تلتهي عنه وهو يشرح ثم تسأله عن نقطة شرحها ، بيزبّد لك قدام الطلاب.\n٧. يهتم بالـ efficiency وهو يصحح الميد والفاينل ، وحسب كلامه انه يخصم على كل سطر زائد عن الحل الأمثل.\n\nالحمد لله أخذت معه قريد ممتاز ، أفضل من اللي توقعته.\nفي المجمل ، الدكتور حبيب وشرحه جيد ، لكني ما أنصح به للي عندهم مشاكل في البرمجة (في هذه المادة بالذات). إذا أنت كويس في البرمجة وما عندك مشكلة مع النقاط اللي ذكرتها ، راح يكون الدكتور خيار جيد لك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479239-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-mohandes/98396/18", "user": "Mr.A1", "ts": 1503569751000, "tid": 98396, "pn": 18}}]}', 1503347995000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11265-ee390', 'stk-user11265', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98396", "n": "Dr. M Mohandes", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nEE390 في 183\nالتحضير : ببداية المحاضرة ويحط تأخير اذا تأخرت 5دقايق اذا كررت تأخيرك يطردك ولا تحضر اليوم اللي تأخرت فيه\nطريقة الشرح : شرحه ممتاز لوتركز معه من سلايداته ويستعمل السبورة للتوضيح وخلك مركز بالشرح اذا حسك انك مومنتبه يطلعك على السبورة تشرح اذا ماعرفت يعطيك احلى تهزيء وطقطقة عليك\nالكويزات : متوسطة الى صعبة مقالي\nالمياجر: صعبة كان هو الوحيد اللي يدرس المادة فكان يجيب اسئلة طويلة للبرمجة\nالفاينلات : صعبة كانت ثلاث اسئلة 2 صعبة 1 متوسط الاسئلة عبارة عن رسمات\nالقريد النهائي:c\nالصوت:ممتاز\nإضافات : الدكتور مزاجي جدا احيانا تشوفه يمزح واحيانا يكون عصبي جدا وانصحك انك تهتم بالشرح والمشاركة اللي يشوفه غير منتبه في شرحه يحقد عليه وكل مرة يطقطق عليه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524991-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-mohandes/98396/21", "user": "user11265", "ts": 1598290354000, "tid": 98396, "pn": 21}}]}', 1598290354000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali1666-ee390', 'stk-ali1666', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 112، EE390\n\nبنود التقييم :\n\nالتحضير : ورقة تمر على الطلاب\n\nطريقة الشرح : حلوة وحيوية، وما يحب الطالب يقعد يستمع، لازم تتفاعل معاه، وساعات أحسه يفصل من زود الحماس ههههه\n\nالكويزات : من سهلة إلى متوسطة، ومن شرحه العظيييم\n\nالمياجر: كومن على ما أذكر، تصحيحه كان حلووو، لاهو شديد ولا متساهل\n\nالفاينلات : كومن، كان الفاينل يبغى له شغل\n\nالقريد النهائي: a\n\nالصوت: واضح وضوح الشمس\n\nإضافات: دكتور فاهم ورائع، ولكن لا تروح له آخر الترم علشان يرفعك قريد، لأنّه ما يحب هالشيء ودايم يهزّئ بطريقة محترمة\n\nموفقين ^^", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1139101-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/10", "user": "Ali1666", "ts": 1355326351000, "tid": 98527, "pn": 10}}]}', 1355326351000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8598-ee390', 'stk-user8598', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 112\n\nee 390\nبنود التقييم :\n\nالتحضير :\nنسيت\nطريقة الشرح :\nعنده نوت يطلب منك تطبعها بداية الترم ويشرح منها\nلكن شرح وافي وكافي ويوضح كل نقطة ويحل عليها امثلة ما يخلصها الا وانت فاهم\nالكويزات :\nسهلة وواضحة جدا\nالمياجر:\nكومون كانت\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nواضح\nإضافات :\n\nالدكتور شريح ومتساهل بالتصحيح واذا جيته الاوفيس وعرفك وكنت تحل الهوموركات كاملة ابشر بالقريد معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1297043-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/13", "user": "user8598", "ts": 1385776106000, "tid": 98527, "pn": 13}}]}', 1385776106000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8552-ee390', 'stk-user8552', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee 390\nبنود التقييم :\n\nالتحضير :\n\nيمشي ورقه وما يحاسب على التأخير وتقدر تحضر في سكشن ثاني\n\nطريقة الشرح :\n\nمن أفضل المدرسين إلي مروا علي في الشرح تقريبا ما تطلع من الليكتشر إلا وأنت فاهم\nيشرح من نوت له ويخليكم تطبعونه في بداية السمستر\n\nالكويزات : متوسطه ويحذف اسوء كوز في النهاية\n\nالمياجر:\n\nكومن كانت لكن متوسطه\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\n\nA+\n\nالصوت:\nواضح\n\nإضافات :\n\nالدكتور ما يتفوت إذا شفت سكشنه فاتح نزل عنده بس مشكلته متمسك بالأفرج لازم يكون c", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1372779-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/14", "user": "user8552", "ts": 1401215330000, "tid": 98527, "pn": 14}}]}', 1401215330000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8714-ee390', 'stk-user8714', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت مع الدكتور كورس EE390\n\nبنود التقييم :\n\nالتحضير :\nيمرر ورقة في بداية المحاضرة, وان تأخرت ممكن تروح له في نهايتها ويحضرك.\n\nطريقة الشرح :\nبإختصار أفضل دكتور مر علي في الجامعة… شرحه مية مية.\nبتفهم معاه غصب عنك.\n\nالكويزات :\nمتوسطة مائلة للسهولة\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور ممتاز جدًا وحرام يضيع عليكم …\nعيبه الوحيييد والقاااتل أن بعض الاسئلة الي يحطها في الميجر مش واضحة …يعني المطلوب مش واضح !! والحركة ذي اتكررت في الميجريين الاول والثاني وفي بعض الكويزات\nبعطيكم مثال:\nأعطانا في الميجر سؤال نكتب كوود معين ووضع فيه شرط … صراحة الشرط رجع السؤال صعب جدًا,نحاول من هنا لهنا مافي فايدة ماينحل …\nبالاخير لما اعطانا الحل اتفاجئنا أن الحل مناقض للشرط !!!\nسألناه قال الشرط فقط عند بداية الحل أما في الاخير ممكن تتجاوزه.\nI was like how am I suppose to know >_<\nوالسؤال عليه ثلث علامة الميجر !! وكلها طارت …\nالطلاب الي ماركزوا ان السؤال فيه شرط جابوا علامات قوية … والي ركز 0 (صفررررررررر)\n\n************************", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1389633-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/15", "user": "user8714", "ts": 1407958136000, "tid": 98527, "pn": 15}}]}', 1407958136000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-ee390', 'stk-magbool', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE390 - 151\n\nبنود التقييم :\n\nالتحضير :\nورقة تمر ، وتقدر تحضر اللي تبغاه 😎\n\nطريقة الشرح :\nالدكتور ذا خبرة في شرح ذا الكورس ، ماشاء الله عليه، شرحه جميل ويحب استخدام أمثلة واقعية عشان تخليك تفهم كيف الكمبيوتر يشتغل، نوته ممتاز ويغني عن الكتاب ، يقلكم أطبعوه بداية الستمستر وجيبه معاك الكلاس عشان ممكن تعدل أو تضيف بعض الأشياء، دايما يهدد إنه حيخصم إذا ماجبت النوت أو إذا ماحليت الأكثلة اللي يكتبها ع السبورة ، بس ماعليك منه يحب يخوف الطلاب بس عشان يشتغلوا.\n\nالكويزات :\nأغلبها سهلة ومباشرة، عبارة عن كتابة برامج.\n\nالمياجر:\nكومن ، وتصحيحه لا بأس به.\n\nالفاينلات :\nكان يتوعدنا غنه حيكون شي مرة صعب، وفي النهاية طلع مرة سهل 🙂\n\nالقريد النهائي: a+\n\nالصوت: واضح والاكسنت هندي بس مفهوم\n\nإضافات :\nدكتور حبيب ورائع ، أظنه أفضل من يدرس EE390", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451073-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/16", "user": "magbool", "ts": 1464989963000, "tid": 98527, "pn": 16}}]}', 1464989963000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-ee390', 'stk-abo-da7m', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f98527", "n": "Dr. Sharif Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE390 الفصل 161\n\nالتحضير :\nورقة تمر على الطلاب ، ما يحاسب على التأخير.\n\nطريقة الشرح :\nشرحه ممتاز ومفيد.\nيفتح نوتاته الخاصة ويشرح ويعلق عليهن ويعدل بعض الأخطاء ويبغاك تطبع النوتات وتتابع معه وتكتب عليهن وتعد الأخطاء اللي يعدلهن.\n\nالكويزات :\nمتوسطات إلى صعبات، يرفعن الضغط شوي لإن خطأ بسيط يلخليك تجيب 3 أو 1 من 10 ! وعليهم 15 من 20 من الكلاس وورك.\n\nالمياجر:\nكومن بينه وبين المدرس الثاني وشكله يكتب نص الأسئلة، الأسئلة اللي منه صعبة وفيها تركات تقهر.\n\nالفاينلات :\nنفس المياجر\n\nالقريد النهائي:\nA إلى A+ كتقييم للدكتور\n\nأما نظامه بتوزيع القريدات أعتقد أنه شديد شوي.\n\nالصوت:\nواضح ومتفهم لو قلت له عد ولا تكلم شوي شوي.\n\nإضافات :\n\n* الدكتور حريص جدا على الطلاب ودايم يعطي نصايح مفيدة بالمادة وبالحياة 🙂\n\n* يشرح بإخلاص وذمة ومستعد يجاوب على كل شيء تبغاه بالفصل أو بالأوفيس إذا ما كفى الوقت.\n\n* يعيب الدكتور أنه يخوفك ويتلكم عن القريدات من بداية الفصل (اللي كذا بياخذ بي واللي كذا بياخذ سي إلخ…) وكلامه موب دقيق من هالناحية فلا تهتم لكلامه.\n\n* صار لي معه مشكلة بأول كوزين وجبت فيهم العيد، المشكلة أن الدكتور يعتمد على نوتاته وترتيبه تماما وأنا اعتمد على الكتاب وترتيبه وكان يقول الكويز شابتر س وأحسبه نفس الكتاب وأذاكر من الكتاب وأتفاجأ بمتيريال مختلف شوي. الكوزين ظلن ناشبات لي لنهاية السمستر لمين حذف واحد. باختصار: اعتمد على نوتاته بالدرجة الأولى إذا بتدرس للكويز.\n\n* كويزاته مثل ما ذكرت فوق يا تاخذ 10 يا 1 (لإنه يسأل عن جزء صغير وعشوائي من ماتيريال الكويز وياتجيبه يا ما تجيبه) وعليهن كثير من الكلاس وورك وأعتقد أنهن أسوأ ما بالدكتور.\n\n* يظل من أفضل الدكاترة إذا بتركز معه وتسجل الملاحظات اللي يقوله أول بأول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467273-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sharif-sheikh/98527/17", "user": "abo-da7m", "ts": 1485768536000, "tid": 98527, "pn": 17}}]}', 1485768536000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-haddad93-ee390', 'stk-haddad93', 'EE 390', 'doc', '{"docs": [{"id": "stk-dr-f169382", "n": "Dr. Asjad Amin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخدت معاه لاب ee390\nاللاب كان لطيف معاه بشكل عام\n• كويزاته تجي مفاجئة … وكان يقولنا قبل ما يعطينا الكويز مرررة سهل، بس كان يجي العكس تماما\n\n• ما كان يعطينا بري لاب …\n• البروجكت في نهاية السمستر كان مرة طويل … بس اتوقع كان كومن.\n\n• اللي استغربت منو انو الافرج نهاية السمستر كان عالي، فنقصنا تقريبا نص درجة.\n\nعموما اللاب هو اصلا خفيف فلا تشيل هم كثير مع مين تنزله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450734-ee390", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/asjad-amin/169382/2", "user": "Haddad93", "ts": 1464625172000, "tid": 169382, "pn": 2}}]}', 1464625172000, 1794826854, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
